class Program {
    static void adjust(int limit, int[] values) {
        limit = 9;
        values[0] += 2;
        values = new int[] {99};
    }
    public static void main(String[] args) {
        int limit = 3;
        int[] values = {5};
        adjust(limit, values);
        System.out.println(limit + " " + values[0]);
    }
}
